// Fwrd posts {"content": "..."} and adds "sender" only when Include Who Sent It is on.
const CODE = /(?<!\d)(\d{3,4})[ -]?(\d{3,4})(?!\d)|(?<!\d)(\d{4,8})(?!\d)/;

return $input.all().map((item) => {
  const body = item.json.body ?? {};
  const text = typeof body.content === 'string' ? body.content : '';
  const m = text.match(CODE);
  return {
    json: {
      text,
      sender: body.sender ?? null,
      code: m ? (m[3] ?? m[1] + m[2]) : null,
      idempotencyKey: item.json.headers?.['idempotency-key'] ?? null,
      receivedAt: new Date().toISOString(),
    },
  };
});
